WITH with_last AS (SELECT s.*, latest.quantity, latest.last_restock FROM products s JOIN LATERAL (SELECT c.quantity, c.last_restock FROM inventory c WHERE c.product_id = s.id AND c.last_restock <= s.launch_date ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT DATE_TRUNC('WEEK', last_restock) AS week_start, CASE WHEN stock_qty >= 363 THEN 'PREMIUM' ELSE 'STANDARD' END AS stock_qty_tier, COUNT(DISTINCT id) AS distinct_ids, BIT_AND(stock_qty) AS stock_qty_bit_and, BIT_AND(stock_qty) AS stock_qty_bit_and_2, COUNT(CASE WHEN brand = 'Umbrella' THEN 1 END) AS umbrella_count, MAX(stock_qty) AS max_stock_qty FROM with_last GROUP BY week_start, stock_qty_tier ORDER BY stock_qty_bit_and
